// 选项卡拖拽落点的纯逻辑。
//
// 用"插入缝隙"而不是"目标选项卡"来描述落点: 拖拽时用户看到的是缝隙中的竖线,
// 而 `moveTab` 需要的是最终槽位。二者之间必须显式换算, 否则会出现
// "拖到最右侧却把竖线画在了最右边选项卡的左侧"这类错位。

import type { WorkbenchTabItem } from './model';

/** 选项卡的几何信息 (由控件测得) */
export interface TabBox {
  id: string;
  /** 相对滚动容器的左边界 */
  left: number;
  width: number;
}

/**
 * 计算拖拽落点。
 *
 * @returns 插入缝隙的下标 `[0, boxes.length]`; 无选项卡时返回 `null`。
 */
export function dropSlot(boxes: TabBox[], pointerX: number): number | null {
  if (boxes.length === 0) return null;

  // 落入某个选项卡的左/右半区 -> 它之前/之后的缝隙
  let slot = boxes.length;
  for (let index = 0; index < boxes.length; index++) {
    const box = boxes[index];
    const center = box.left + box.width / 2;
    if (pointerX < center) {
      slot = index;
      break;
    }
  }

  return slot;
}

/**
 * 把插入缝隙换算成 `moveTab` 需要的目标槽位。
 *
 * @returns 目标下标; 无需移动时返回 `null`。
 */
export function slotToIndex(tabs: WorkbenchTabItem[], draggedId: string, slot: number): number | null {
  const from = tabs.findIndex((tab) => tab.id === draggedId);
  if (from < 0) return null;
  // 拖动前后的缝隙: 落在自身左右两侧都表示"位置不变"
  if (slot === from || slot === from + 1) return null;
  const insertAt = slot > from ? slot - 1 : slot;
  return Math.max(0, Math.min(insertAt, tabs.length - 1));
}

/** 竖线应画在哪个选项卡的哪一侧; `null` 表示不显示 */
export interface DropIndicator {
  id: string;
  side: 'before' | 'after';
}

export function dropIndicator(tabs: WorkbenchTabItem[], draggedId: string, slot: number | null): DropIndicator | null {
  if (slot === null) return null;
  const from = tabs.findIndex((tab) => tab.id === draggedId);
  // 落回原位 (自身左侧或右侧的缝隙) 不显示指示
  if (from >= 0 && (slot === from || slot === from + 1)) return null;

  if (slot >= tabs.length) {
    const last = tabs[tabs.length - 1];
    return last ? { id: last.id, side: 'after' } : null;
  }

  const target = tabs[slot];
  return target ? { id: target.id, side: 'before' } : null;
}
